commits.content:
:root {
  color-scheme: light;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  background: #eef2f6;
  color: #17202a;
  --border: #d8e1ea;
  --muted: #637587;
  --panel: #ffffff;
  --panel-soft: #f8fafc;
  --good: #14804a;
  --good-bg: #e2f6ea;
  --bad: #b4232f;
  --bad-bg: #fde8e8;
  --accent: #0f6f8f;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
}

button,
input,
select {
  font: inherit;
}

.app-shell {
  width: min(1440px, calc(100% - 36px));
  margin: 0 auto;
  padding: 22px 0 28px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 64px;
  margin-bottom: 16px;
}

.brand,
.actions,
.panel-heading,
.workbench {
  display: flex;
  align-items: center;
}

.brand {
  gap: 12px;
}

.brand-mark {
  width: 38px;
  height: 38px;
  border-radius: 8px;
  background:
    linear-gradient(90deg, transparent 42%, rgba(255, 255, 255, 0.9) 42% 58%, transparent 58%),
    linear-gradient(0deg, transparent 42%, rgba(255, 255, 255, 0.9) 42% 58%, transparent 58%),
    #126f8c;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.08);
}

.brand p,
.panel-heading p,
.table-header p {
  margin: 0;
  color: var(--muted);
  font-size: 0.84rem;
}

h1,
h2 {
  margin: 0;
  letter-spacing: 0;
}

h1 {
  font-size: 1.85rem;
  line-height: 1.1;
}

h2 {
  font-size: 1rem;
}

.actions {
  gap: 10px;
}

button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  border: 0;
  border-radius: 7px;
  padding: 0 14px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  font-weight: 800;
}

button:disabled {
  cursor: wait;
  opacity: 0.66;
}

.button-icon {
  font-size: 1rem;
  line-height: 1;
}

.sync-pill,
.plc-chip {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0 11px;
  background: var(--panel);
  color: #425466;
  font-size: 0.84rem;
  font-weight: 700;
}

.overview {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 10px;
}

.metric-card,
.quality-panel,
.panel-card,
.table-section {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--panel);
}

.metric-card {
  min-height: 108px;
  padding: 14px 16px;
}

.metric-card span,
dt,
label {
  color: var(--muted);
  font-size: 0.82rem;
}

.metric-card strong {
  display: block;
  margin: 7px 0 3px;
  font-size: 1.9rem;
  line-height: 1;
}

.metric-card small {
  color: var(--muted);
  font-size: 0.82rem;
}

.metric-card.good strong,
.metric-card.good small {
  color: var(--good);
}

.metric-card.bad strong,
.metric-card.bad small {
  color: var(--bad);
}

.quality-panel {
  padding: 14px 16px;
  margin-bottom: 10px;
}

.panel-heading {
  justify-content: space-between;
  gap: 12px;
}

.panel-heading.compact {
  margin-bottom: 10px;
}

.quality-track {
  display: flex;
  width: 100%;
  height: 12px;
  margin-top: 14px;
  overflow: hidden;
  border-radius: 999px;
  background: #e8eef4;
}

.quality-track span {
  display: block;
  min-width: 0;
  transition: width 180ms ease;
}

.quality-good {
  width: 0%;
  background: var(--good);
}

.quality-bad {
  width: 0%;
  background: var(--bad);
}

.workbench {
  align-items: stretch;
  gap: 10px;
}

.side-panel {
  display: grid;
  width: 340px;
  flex: 0 0 340px;
  gap: 10px;
  align-content: start;
}

.panel-card {
  padding: 14px;
}

.connection-list {
  display: grid;
  gap: 10px;
  margin: 12px 0 0;
}

.compact-list {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

dt {
  margin-bottom: 3px;
}

dd {
  margin: 0;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.compact-list dd {
  font-size: 0.92rem;
}

label {
  display: block;
  margin-top: 12px;
}

input,
select {
  width: 100%;
  height: 39px;
  margin-top: 6px;
  border: 1px solid #cbd7e3;
  border-radius: 7px;
  padding: 0 10px;
  background: var(--panel-soft);
  color: #17202a;
}

input:focus,
select:focus,
button:focus-visible {
  outline: 3px solid rgba(15, 111, 143, 0.22);
  outline-offset: 1px;
}

.error {
  margin: 12px 0 0;
  color: var(--bad);
  font-weight: 800;
}

.bad-list {
  display: grid;
  gap: 7px;
  max-height: 230px;
  margin: 0;
  padding: 0;
  overflow: auto;
  list-style: none;
}

.bad-list li {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  border-radius: 7px;
  padding: 8px 9px;
  background: var(--bad-bg);
  color: var(--bad);
  font-size: 0.84rem;
  font-weight: 800;
}

.bad-list small {
  color: #7d2b31;
  font-weight: 700;
}

.table-section {
  min-width: 0;
  flex: 1;
  overflow: hidden;
}

.table-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 14px;
  border-bottom: 1px solid var(--border);
}

.table-wrap {
  height: min(62vh, 680px);
  overflow: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

th,
td {
  padding: 9px 11px;
  border-bottom: 1px solid #edf2f6;
  text-align: left;
  white-space: nowrap;
}

th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #e9f0f6;
  color: #33475b;
  font-size: 0.75rem;
  text-transform: uppercase;
}

tbody tr:hover {
  background: #f7fafc;
}

td:nth-child(2) {
  min-width: 300px;
  white-space: normal;
  overflow-wrap: anywhere;
  font-weight: 700;
}

.badge {
  display: inline-flex;
  min-width: 60px;
  justify-content: center;
  border-radius: 999px;
  padding: 3px 8px;
  font-size: 0.76rem;
  font-weight: 900;
}

.badge.good {
  background: var(--good-bg);
  color: var(--good);
}

.badge.bad {
  background: var(--bad-bg);
  color: var(--bad);
}

.empty {
  padding: 38px 12px;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 980px) {
  .overview {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .workbench {
    flex-direction: column;
  }

  .side-panel {
    width: 100%;
    flex-basis: auto;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .app-shell {
    width: min(100% - 20px, 1440px);
    padding: 16px 0;
  }

  .topbar,
  .actions,
  .table-header {
    align-items: stretch;
    flex-direction: column;
  }

  .overview,
  .side-panel {
    grid-template-columns: 1fr;
  }

  button {
    width: 100%;
  }


}
